106	/// Spinner creation and management.
107	pub trait SpinnerFactory {
108	    /// Start a spinner for an operation.
109	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle>;
110	
111	    /// Start a spinner with leading indentation.
112	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
113	        let _ = indent;
114	        self.start_spinner(message)
115	    }
116	}
