148	/// Combined trait for all generic user interface interactions.
149	///
150	/// Run-path workflow chrome and per-step rendering are *not* part of
151	/// this trait — see [`crate::runner::display`] for those concerns. This
152	/// trait is intentionally narrow so that init / status / list / lint
153	/// commands can mock it without dragging in workflow types.
154	pub trait UserInterface:
155	    OutputWriter + Prompter + SpinnerFactory + ProgressDisplay + UiState
156	{
157	}
158	
159	impl<T> UserInterface for T where
160	    T: OutputWriter + Prompter + SpinnerFactory + ProgressDisplay + UiState
161	{
162	}
