258	
259	        // Ring buffer evicts oldest line
260	        callback.write_line(OutputLine::Stdout("line 3".to_string()));
261	        let msg = bar.message();
262	        assert!(!msg.contains("line 1"));
263	        assert!(msg.contains("line 2"));
264	        assert!(msg.contains("line 3"));
265	
266	        bar.finish();
267	    }
268	
269	    #[test]
270	    fn live_output_callback_skips_empty_lines() {
271	        let bar = ProgressBar::hidden();
272	        let callback = live_output_callback(bar.clone(), "Running...".to_string(), 4, 2);
273	
274	        // Send an empty line — should not cause a newline in the message
275	        callback.write_line(OutputLine::Stdout("".to_string()));
276	
277	        // Now send a real line — the message should have exactly one output line
278	        callback.write_line(OutputLine::Stdout("real output".to_string()));
279	        let msg = bar.message();
280	        assert!(msg.contains("real output"));
281	        // Only one newline (base message + one output line)
282	        assert_eq!(msg.matches('\n').count(), 1);
283	
284	        bar.finish();
285	    }
