    fn attach_surface(&mut self, _surface: Arc<TerminalSurface>) {}
    fn detach_surface(&mut self) {}
}

// Blanket trait combining all above
pub trait UserInterface: OutputWriter + Prompter + SpinnerFactory + ProgressDisplay + UiState {}
```

