294	impl Prompter for TerminalStepDisplay {
295	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
296	        // Re-claim foreground process group before each prompt — child
297	        // commands may have stolen it on exit.
298	        #[cfg(unix)]
299	        claim_foreground();
300	
301	        let term = console::Term::stdout();
302	        self.surface
303	            .with_cursor_freed(|| prompt_user(prompt, &term))
304	    }
305	}
