52	/// Returns true when `TERM=dumb`.
53	///
54	/// Dumb terminals don't support cursor movement, so interactive redraws
55	/// (clear-and-repaint cycles) produce garbage output. When true, prompts
56	/// render forward-only and `clear_lines` becomes a no-op.
57	pub(crate) fn is_dumb_term() -> bool {
58	    std::env::var("TERM").map(|v| v == "dumb").unwrap_or(false)
59	}
60	
61	use crate::error::Result;
62	use indicatif::ProgressBar;
63	
64	/// Output methods for displaying messages, warnings, errors, and hints.
65	pub trait OutputWriter {
66	    /// Display a message to the user.
67	    fn message(&mut self, msg: &str);
68	
69	    /// Display a success message.
70	    fn success(&mut self, msg: &str);
71	
72	    /// Display a warning message.
73	    fn warning(&mut self, msg: &str);
74	
75	    /// Display an error message.
76	    fn error(&mut self, msg: &str);
77	
78	    /// Show a contextual hint to the user.
79	    fn show_hint(&mut self, hint: &str) {
80	        self.message(hint);
81	    }
82	
83	    /// Show a bordered error block with command, output, and optional hint.
84	    ///
85	    /// `indent` is the column at which the block should align (typically the
86	    /// step number width, so error content lines up under the step name).
87	    /// Implementations that don't render a visual box may ignore it.
88	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
89	        let _ = indent;
90	        self.error(command);
91	        if !output.is_empty() {
92	            self.message(output);
93	        }
94	        if let Some(h) = hint {
95	            self.show_hint(h);
96	        }
97	    }
98	}
99	
100	/// Interactive prompting.
101	pub trait Prompter {
102	    /// Show a prompt and get user input.
103	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult>;
104	}
105	
106	/// Spinner creation and management.
107	pub trait SpinnerFactory {
108	    /// Start a spinner for an operation.
109	    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle>;
110	
111	    /// Start a spinner with leading indentation.
112	    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
113	        let _ = indent;
114	        self.start_spinner(message)
115	    }
116	}
117	
118	/// Headers and progress indicators.
119	pub trait ProgressDisplay {
120	    /// Show a header/banner.
121	    fn show_header(&mut self, title: &str);
122	
123	    /// Show progress (e.g., "Step 3 of 7").
124	    fn show_progress(&mut self, current: usize, total: usize);
125	}
126	
127	/// Output mode and interactivity state.
128	pub trait UiState {
129	    /// Get the current output mode.
130	    fn output_mode(&self) -> OutputMode;
131	
132	    /// Check if running in interactive mode.
133	    fn is_interactive(&self) -> bool;
134	
135	    /// Change the output mode at runtime.
136	    fn set_output_mode(&mut self, mode: OutputMode);
137	
138	    /// Attach a [`crate::ui::surface::TerminalSurface`] for the
139	    /// duration of a run. Default impl is a no-op for UIs that have no
140	    /// surface concept (mock, non-interactive). Only `TerminalUI`
141	    /// overrides this.
142	    fn attach_surface(&mut self, _surface: std::sync::Arc<crate::ui::surface::TerminalSurface>) {}
143	
144	    /// Detach the surface attached by [`Self::attach_surface`].
145	    fn detach_surface(&mut self) {}
146	}
