191	/// A prompt to show to the user.
192	#[derive(Debug, Clone)]
193	pub struct Prompt {
194	    /// Unique key for the prompt (used for caching/lookup).
195	    pub key: String,
196	    /// The question to display.
197	    pub question: String,
