234	    Strings(Vec<String>),
235	}
236	
237	impl PromptResult {
238	    /// Get as string, suitable for interpolation.
239	    pub fn as_string(&self) -> String {
240	        match self {
241	            Self::Bool(b) => b.to_string(),
242	            Self::String(s) => s.clone(),
243	            Self::Strings(v) => v.join(","),
244	        }
245	    }
246	
247	    /// Get as bool if this is a Bool result.
248	    pub fn as_bool(&self) -> Option<bool> {
249	        match self {
250	            Self::Bool(b) => Some(*b),
251	            _ => None,
252	        }
253	    }
254	}
255	
256	#[cfg(test)]
257	mod tests {
258	    use super::*;
259	
260	    #[test]
261	    fn prompt_result_as_string_bool() {
262	        assert_eq!(PromptResult::Bool(true).as_string(), "true");
263	        assert_eq!(PromptResult::Bool(false).as_string(), "false");
264	    }
265	
266	    #[test]
267	    fn prompt_result_as_string_string() {
