334	    #[test]
335	    fn prompt_type_select_stores_options() {
336	        let options = vec![
337	            PromptOption {
338	                label: "Option A".to_string(),
339	                value: "a".to_string(),
340	            },
341	            PromptOption {
342	                label: "Option B".to_string(),
343	                value: "b".to_string(),
344	            },
345	        ];
346	
347	        let prompt_type = PromptType::Select {
348	            options: options.clone(),
349	        };
350	
351	        if let PromptType::Select { options: stored } = prompt_type {
352	            assert_eq!(stored.len(), 2);
353	            assert_eq!(stored[0].value, "a");
354	        } else {
355	            panic!("Expected Select variant");
356	        }
357	    }
358	
359	    #[test]
360	    fn prompt_type_multiselect_stores_options() {
361	        let options = vec![PromptOption {
362	            label: "Feature 1".to_string(),
363	            value: "f1".to_string(),
364	        }];
365	
366	        let prompt_type = PromptType::MultiSelect { options };
367	
368	        if let PromptType::MultiSelect { options: stored } = prompt_type {
369	            assert_eq!(stored.len(), 1);
370	        } else {
371	            panic!("Expected MultiSelect variant");
372	        }
373	    }
