250	        let msg = bar.message();
251	        assert!(msg.contains("Running..."));
252	        assert!(msg.contains("line 1"));
253	
254	        callback.write_line(OutputLine::Stderr("line 2".to_string()));
255	        let msg = bar.message();
256	        assert!(msg.contains("line 1"));
257	        assert!(msg.contains("line 2"));
258	
259	        // Ring buffer evicts oldest line
260	        callback.write_line(OutputLine::Stdout("line 3".to_string()));
261	        let msg = bar.message();
262	        assert!(!msg.contains("line 1"));
263	        assert!(msg.contains("line 2"));
